<script>
  import { canOperate } from './cockpit.js'
  import Modal from './CockpitModal.svelte'
  import { onMount } from 'svelte'
  import { apiGet, apiPut } from './api.js'
  import { url, STATUS, csv } from './cockpit.js'
  import { msApi, followJob } from './managed.js'
  import { fmtDateTime } from './product.js'
  let { tenant } = $props()
  let checks = $state([]), error = $state(''), loading = $state(false), filter = $state('all'), edit = $state(null), status = $state('fulfilled'), note = $state(''), saving = $state(false)
  let shown = $derived(checks.filter(c => filter === 'all' || c.status === filter))
  let applicable = $derived(checks.filter(c => c.status !== 'na'))
  let percent = $derived(applicable.length ? Math.round(checks.filter(c => c.status === 'fulfilled').length / applicable.length * 100) : null)
  async function load() { loading = true; error = ''; try { checks = (await apiGet(url(tenant.id, 'compliance'))).checks } catch(e) { error = e.message }; loading = false }
  async function scan() { loading = true; error = ''; try { const j = await msApi.run(tenant.id,['ca','risk','sharing','devices','threat']); const r = await followJob(j.jobId); if (!r || r.status !== 'done') throw new Error(r?.error || 'Scan fehlgeschlagen'); await load() } catch(e) { error = e.message }; loading = false }
  async function save() { saving = true; try { await apiPut(url(tenant.id,`compliance/${edit.id}`), { status, note }); edit = null; await load() } catch(e) { error = e.message }; saving = false }
  onMount(load)
</script>
<div class="cp-head"><div><h2>DSGVO Compliance Check</h2><p>{tenant.name} · Technische und organisatorische Maßnahmen</p></div><div class="cp-actions"><strong style="font-size:30px;color:var(--accent)">{percent ?? '—'}%</strong><button class="btn btn-secondary" onclick={() => csv('Maßnahmen',['Maßnahme','Prüfart','Status','Nachweis','Zeitpunkt'],checks.map(c => [c.title,c.manual ? 'Manuell' : 'Technisch',STATUS[c.status],c.evidence?.note,c.evidence?.at || c.at]))}>Maßnahmen exportieren</button><button class="btn btn-primary" disabled={loading || !canOperate(tenant)} onclick={scan}>{loading ? 'Scan läuft…' : 'Scan starten'}</button></div></div>
<section class="cp-panel"><h3>So funktioniert der Check</h3><p>Technische Maßnahmen lesen die letzte Managed-Service-Erhebung. Organisatorische Maßnahmen bestätigst du mit einer Begründung oder einem Verweis auf deinen Nachweis. Der Erfüllungsgrad zählt dokumentierte Maßnahmen; unbekannte technische Zustände gelten als zu prüfen.</p><div class="cp-note" style="margin:14px 0 0">Diese Arbeitsliste ist kein Nachweis vollständiger rechtlicher Konformität. Technische Kategorien sind Befundübersichten; ein unauffälliger Scan belegt allein keine vollständige Umsetzung aller Anforderungen.</div></section>
{#if error}<div class="cp-note cp-gaps" role="alert">{error}</div>{/if}
<div class="cp-kpis">{#each [['all','Maßnahmen gesamt'],['fulfilled','Erfüllt'],['open','Offen'],['unknown','Zu prüfen']] as [id,label]}<button class="cp-kpi" class:active={filter === id} onclick={() => filter = id}><span>{label}</span><strong>{id === 'all' ? checks.length : checks.filter(c => c.status === id).length}</strong></button>{/each}</div>
{#each [[false,'Technische Maßnahmen — automatisch geprüft'],[true,'Organisatorische Maßnahmen — manuell dokumentiert']] as [manual,title]}<section class="cp-panel"><h3>{title}</h3><div class="cp-table-wrap" style="margin-top:18px"><table><thead><tr><th>Maßnahme</th><th>Status</th><th>Nachweis / Stand</th><th></th></tr></thead><tbody>{#each shown.filter(c => c.manual === manual) as c}<tr><td><strong>{c.title}</strong><small>{c.article || `${c.findings ?? 0} offene Befunde`}</small></td><td><span class="cp-badge" class:ok={c.status === 'fulfilled'} class:high={c.status === 'open'}>{STATUS[c.status]}</span></td><td style="white-space:normal;max-width:440px">{c.evidence?.note || '—'}<small>{fmtDateTime(c.evidence?.at || c.at)}{c.evidence?.by ? ' · ' + c.evidence.by : ''}</small></td><td>{#if manual}<button class="btn btn-secondary" disabled={!canOperate(tenant)} onclick={() => { edit = c; note = c.evidence?.note || ''; status = c.status }}>Dokumentieren</button>{/if}</td></tr>{:else}<tr><td colspan="4">Keine Maßnahmen in diesem Filter.</td></tr>{/each}</tbody></table></div></section>{/each}
{#if edit}<Modal {error} label="Maßnahme dokumentieren" onclose={() => edit = null} busy={saving}><h3>{edit.title}</h3><label>Status<select bind:value={status}>{#each Object.entries(STATUS) as [id,label]}<option value={id}>{label}</option>{/each}</select></label><label>Begründung / Nachweisreferenz<textarea bind:value={note} maxlength="4000" placeholder="Dokument, Ablageort, Prüfdatum und Ergebnis…"></textarea></label><div class="cp-actions"><button class="btn btn-secondary" disabled={saving} onclick={() => edit = null}>Abbrechen</button><button class="btn btn-primary" onclick={save} disabled={!note.trim() || saving}>Speichern</button></div></Modal>{/if}
